t = {}
for k, n, d in B:
    if k in EN: t[n] = EN[k][0]
pp = []
for k, n, d in B:
    if k not in EN: continue
    keys = re.findall(r'\{([a-z]+%?)\}', d)
    rx = '^' + re.sub(r'\\\{[a-z]+%?\\\}', '(.+?)', re.escape(d)) + '$'
    en = EN[k][1].replace('$', '$$')
    for i, key in enumerate(keys): en = en.replace('{' + key + '}', '$' + str(i + 1))
    if not keys: t[d] = EN[k][1]
    else: pp.append([rx, en])
t.update(DESP); t.update(UI)
NOMBRES = '|'.join(re.escape(n) for _, n, _ in B)
pp.append(['^(' + NOMBRES + ') y (' + NOMBRES + ')$', '$1 and $2'])
pp += P
json.dump({'t': t, 'p': pp}, open(D + 'en_balas.json', 'w'), ensure_ascii=False, indent=0)
print('textos', len(t), 'plantillas', len(pp))
